        { future, continuation -> UniffiLib.INSTANCE.ffi_phantom_core_rust_future_complete_rust_buffer(future, continuation) },
        { future -> UniffiLib.INSTANCE.ffi_phantom_core_rust_future_free_rust_buffer(future) },
