/**
 * Connection state for `PhantomSession`.
 *
 * The session is usable from the moment it's created — sends are queued
 * until the handshake completes.
 */

enum class ConnectionState(val value: kotlin.UByte) {
    
    /**
     * Connection initiated, handshake pending
     */
    CONNECTING(0u),
    /**
     * Classical (X25519) channel established — data flows
     */
    CLASSICAL_READY(1u),
    /**
     * PQC upgrade in progress
     */
    PQC_UPGRADING(2u),
    /**
     * Full hybrid PQC protection active
     */
    PQC_READY(3u),
    /**
     * Fully connected and operational
     */
    CONNECTED(4u),
    /**
     * Connection failed
     */
    FAILED(5u),
    /**
     * Gracefully closed
     */
    CLOSED(6u);
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeConnectionState: FfiConverterRustBuffer<ConnectionState> {
    override fun read(buf: ByteBuffer) = try {
        ConnectionState.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: ConnectionState) = 4UL

    override fun write(value: ConnectionState, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * Universal Core Error Enum compatible with FFI exports
 */
sealed class CoreException: kotlin.Exception() {
    
    class NetworkException(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class SerializationException(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Busy(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class ConfigException(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class CryptoException(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class ValidationException(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class RuntimeException(
        
        val v1: kotlin.String
